changeSet.sql:
DECLARE
    v_count           NUMBER;
    v_max_flow_key    NUMBER;
    v_target_nextval  NUMBER;
BEGIN
    /*
     * The canonical sequence must exist in MEDIATION.
     */
    SELECT COUNT(*)
      INTO v_count
      FROM ALL_SEQUENCES
     WHERE SEQUENCE_OWNER = 'MEDIATION'
       AND SEQUENCE_NAME = 'FLOWS_SEQ';

    IF v_count = 0 THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'MEDIATION.FLOWS_SEQ does not exist'
        );
    END IF;

    /*
     * Hibernate runs as MEDPORTAL, therefore the application schema must
     * have a direct SELECT privilege on the canonical sequence.
     */
    SELECT COUNT(*)
      INTO v_count
      FROM ALL_TAB_PRIVS
     WHERE TABLE_SCHEMA = 'MEDIATION'
       AND TABLE_NAME = 'FLOWS_SEQ'
       AND GRANTEE = 'MEDPORTAL'
       AND PRIVILEGE = 'SELECT';

    IF v_count = 0 THEN
        RAISE_APPLICATION_ERROR(
            -20002,
            'MEDPORTAL requires SELECT on MEDIATION.FLOWS_SEQ'
        );
    END IF;

    /*
     * Never switch to a sequence that can still generate an existing
     * TBL_FLOWS primary key. NEXTVAL consumption here is intentional and
     * harmless; sequence values are not required to be gap-free.
     */
    SELECT NVL(MAX(FLOW_KEY), 0)
      INTO v_max_flow_key
      FROM MEDPORTAL.TBL_FLOWS;

    SELECT MEDIATION.FLOWS_SEQ.NEXTVAL
      INTO v_target_nextval
      FROM DUAL;

    IF v_target_nextval <= v_max_flow_key THEN
        RAISE_APPLICATION_ERROR(
            -20003,
            'MEDIATION.FLOWS_SEQ is not ahead of TBL_FLOWS.FLOW_KEY; next='
            || v_target_nextval
            || ', max='
            || v_max_flow_key
        );
    END IF;

    /*
     * A private MEDPORTAL sequence shadows a synonym with the same name.
     * Remove it if an older deployment created one.
     */
    SELECT COUNT(*)
      INTO v_count
      FROM USER_SEQUENCES
     WHERE SEQUENCE_NAME = 'FLOWS_SEQ';

    IF v_count > 0 THEN
        EXECUTE IMMEDIATE 'DROP SEQUENCE FLOWS_SEQ';
    END IF;

    /*
     * Keep the existing unqualified Hibernate @SequenceGenerator mapping:
     * FLOWS_SEQ now resolves to the canonical MEDIATION sequence.
     */
    EXECUTE IMMEDIATE
        'CREATE OR REPLACE SYNONYM FLOWS_SEQ FOR MEDIATION.FLOWS_SEQ';
END;
